/**
 * @file test_backoff.cpp
 * @brief 有界指数退避算法单元测试（TWIN-04 / TWIN-51）
 */

#include "../../common/service_lifecycle.h"
#include <stdio.h>
#include <string.h>
/* 确保在 Release (-DNDEBUG) 构建下单元测试断言依然生效且不产生未使用变量告警 */
#undef NDEBUG
#include <assert.h>

/**
 * @brief 验证有界退避接口的空指针防御卫语句
 * @return 无返回值；任一断言失败时终止测试进程
 */
static void test_backoff_null_guards(void)
{
    /* 显式零初始化栈上结构体，消除 GCC 15 下传入 const 指针形参触发的 -Werror=maybe-uninitialized */
    backoff_state_t st = {0U, 0U, 0ULL, false};
    backoff_config_t cfg = {0U, 0U, 0U, 0U, 0U};
    uint32_t delay = 0U;
    bool exhausted = false;

    /* 逐项校验初始化、重置、延迟计算与耗尽判定的空指针入参拦截 */
    assert(backoff_init(NULL, &cfg) == LIFECYCLE_ERR_INVALID_ARGUMENT);
    assert(backoff_init(&st, NULL) == LIFECYCLE_ERR_INVALID_ARGUMENT);
    assert(backoff_reset(NULL, &cfg) == LIFECYCLE_ERR_INVALID_ARGUMENT);
    assert(backoff_next_delay(NULL, &cfg, &delay) == LIFECYCLE_ERR_INVALID_ARGUMENT);
    assert(backoff_next_delay(&st, &cfg, NULL) == LIFECYCLE_ERR_INVALID_ARGUMENT);
    assert(backoff_is_exhausted(NULL, &cfg, &exhausted) == LIFECYCLE_ERR_INVALID_ARGUMENT);
    printf("PASS: test_backoff_null_guards\n");
}

/**
 * @brief 验证有界指数退避延迟倍增、上限封顶与重试次数耗尽状态转换
 * @return 无返回值；任一断言失败时终止测试进程
 */
static void test_backoff_progression(void)
{
    /* 显式零初始化退避配置与状态结构体，避免未初始化栈内存告警 */
    backoff_config_t cfg = {0U, 0U, 0U, 0U, 0U};
    cfg.initial_interval_ms = 500U;
    cfg.max_interval_ms = 3000U;
    cfg.multiplier_num = 2U;
    cfg.multiplier_den = 1U;
    cfg.max_retries = 4U;

    backoff_state_t st = {0U, 0U, 0ULL, false};
    assert(backoff_init(&st, &cfg) == LIFECYCLE_OK);

    uint32_t delay = 0U;
    /* 第 1 次重试：返回初始间隔 500 ms，下一次间隔倍增为 1000 ms */
    assert(backoff_next_delay(&st, &cfg, &delay) == LIFECYCLE_OK);
    assert(delay == 500U);
    assert(st.retry_count == 1U);

    /* 第 2 次重试：返回 1000 ms，下一次间隔倍增为 2000 ms */
    assert(backoff_next_delay(&st, &cfg, &delay) == LIFECYCLE_OK);
    assert(delay == 1000U);
    assert(st.retry_count == 2U);

    /* 第 3 次重试：返回 2000 ms，下一次间隔按上限 3000 ms 封顶 */
    assert(backoff_next_delay(&st, &cfg, &delay) == LIFECYCLE_OK);
    assert(delay == 2000U);
    assert(st.retry_count == 3U);

    /* 第 4 次重试：返回封顶值 3000 ms，达到最大重试次数 max_retries = 4 并置位耗尽标志 */
    assert(backoff_next_delay(&st, &cfg, &delay) == LIFECYCLE_OK);
    assert(delay == 3000U);
    assert(st.retry_count == 4U);
    assert(st.is_exhausted == true);

    /* 第 5 次重试：已达上限，返回 LIFECYCLE_ERR_EXHAUSTED 且输出延迟清零 */
    assert(backoff_next_delay(&st, &cfg, &delay) == LIFECYCLE_ERR_EXHAUSTED);
    assert(delay == 0U);

    bool is_ex = false;
    assert(backoff_is_exhausted(&st, &cfg, &is_ex) == LIFECYCLE_OK);
    assert(is_ex == true);

    printf("PASS: test_backoff_progression\n");
}

/**
 * @brief 验证退避状态重置后计数、当前间隔与耗尽标志恢复初始值
 * @return 无返回值；任一断言失败时终止测试进程
 */
static void test_backoff_reset(void)
{
    /* 显式零初始化退避配置与状态结构体，消除未初始化局部变量告警 */
    backoff_config_t cfg = {0U, 0U, 0U, 0U, 0U};
    cfg.initial_interval_ms = 200U;
    cfg.max_interval_ms = 1000U;
    cfg.multiplier_num = 2U;
    cfg.multiplier_den = 1U;
    cfg.max_retries = 3U;

    backoff_state_t st = {0U, 0U, 0ULL, false};
    assert(backoff_init(&st, &cfg) == LIFECYCLE_OK);

    uint32_t delay = 0U;
    assert(backoff_next_delay(&st, &cfg, &delay) == LIFECYCLE_OK);
    assert(st.retry_count == 1U);

    /* 重置退避状态并校验计数、当前间隔与耗尽标志恢复初始态 */
    assert(backoff_reset(&st, &cfg) == LIFECYCLE_OK);
    assert(st.retry_count == 0U);
    assert(st.current_interval_ms == 200U);
    assert(st.is_exhausted == false);

    printf("PASS: test_backoff_reset\n");
}

/**
 * @brief 有界指数退避单元测试主入口
 * @return int 全部测试通过返回 0
 */
int main(void)
{
    printf("Running Bounded Backoff Unit Tests...\n");
    test_backoff_null_guards();
    test_backoff_progression();
    test_backoff_reset();
    printf("ALL Bounded Backoff Unit Tests PASSED!\n");
    return 0;
}

